      "questionEn": "A uniform rod $AB$ of length $120\\text{ cm}$ and weight $W = 60\\text{ N}$ is hinged at $A$. An external couple of moment $M = 1800\\text{ N}\\cdot\\text{cm}$ acts on the rod tending to rotate it clockwise. A light tie cable attached to end $B$ holds the rod horizontally, making an angle of $30^\\circ$ with the rod. What is the tension $T$ in the cable?",
      "questionAr": "قضيب منتظم $AB$ طوله $120\\text{ cm}$ ووزنه $W = 60\\text{ N}$ مثبت بمفصل عند $A$. أثر على القضيب ازدواج خارجي عزمه $M = 1800\\text{ N}\\cdot\\text{cm}$ مع عقارب الساعة. حبل خفيف مربوط عند الطرف $B$ يحفظ القضيب أفقياً ويميل بزاوية $30^\\circ$ على القضيب. ما مقدار الشد $T$ في الحبل؟",
      "optionsEn": [
        "$90\\text{ N}$",
        "$60\\text{ N}$",
        "$120\\text{ N}$",
        "$45\\text{ N}$"
      ],
      "optionsAr": [
        "90 نيوتن",
        "60 نيوتن",
        "120 نيوتن",
        "45 نيوتن"
      ],
      "correctAnswer": "$90\\text{ N}$",
      "correctIndex": 0,
      "hintEn": "Moments about hinge $A$: $T \\sin 30^\\circ \\times 120 - W \\times 60 - M = 0 \\implies 60 T - 3600 - 1800 = 0 \\implies 60 T = 5400 \\implies T = 90\\text{ N}$.",
      "hintAr": "بالعزوم حول المفصل أ: ش جا 30 × 120 - 60 × 60 - 1800 = 0، إذن 60 ش = 5400، ومنها ش = 90 نيوتن.",
      "stepByStepSolutionEn": [
        "1. Take moments about the hinge $A$ to eliminate the unknown hinge reactions.",
        "2. Upward vertical component of tension is $T_y = T \\sin 30^\\circ = 0.5 T$, with lever arm $AB = 120\\text{ cm}$.",
        "   Moment of tension $= 0.5 T \\times 120 = 60 T$ (counterclockwise).",
        "3. Downward weight $W = 60\\text{ N}$ acts at midpoint, lever arm $= 60\\text{ cm}$.",
        "   Moment of weight $= 60 \\times 60 = 3600\\text{ N}\\cdot\\text{cm}$ (clockwise).",
        "4. The applied couple is clockwise: $M = 1800\\text{ N}\\cdot\\text{cm}$.",
        "5. Static equilibrium: $60 T - 3600 - 1800 = 0 \\implies 60 T = 5400 \\implies T = 90\\text{ N}$."
      ],
      "stepByStepSolutionAr": [
        "١. بأخذ العزوم حول المفصل $A$ للتخلص من ردود أفعاله المجهولة.",
        "٢. المركبة الرأسية للشد: $T \\sin 30^\\circ = 0.5 T$، وذراعها $120$ سم، فعزمها $60 T$ ضد عقارب الساعة.",
        "٣. عزم الوزن حول $A$: $60 \\times 60 = 3600$ نيوتن.سم مع عقارب الساعة.",
        "٤. عزم الازدواج المؤثر: $1800$ نيوتن.سم مع عقارب الساعة.",
        "٥. معادلة الاتزان: $60 T = 3600 + 1800 = 5400 \\implies T = 90$ نيوتن."
      ],
      "teacherTipEn": "Couples simply enter the moment equation as a pure constant scalar term $\\pm M$, independent of position.",
      "teacherTipAr": "يدخل عزم الازدواج في معادلة العزوم كحد قياسي ثابت مستقل تماماً عن نقطة أخذ العزم."
