      "questionAr": "صفيحة مربعة منتظمة $ABCD$ طول ضلعها $20\\text{ cm}$ ووزنها $40\\text{ N}$ قُطع منها مربع صغير عند الرأس $C$ طول ضلعه $10\\text{ cm}$. عُلقت الصفيحة المتبقية حراً من $A$. ما بعد مركز ثقل الجزء المتبقي عن الضلع $AB$؟",
