        "3. Cutout square at corner $C(20, 20)$: side $10\\text{ cm}$, area $A_2 = 100$, center $G_2(15, 15)$.",
        "4. Remaining area: $A = 400 - 100 = 300\\text{ cm}^2$.",
        "5. Apply negative mass method for distance from $AB$ (y-coordinate):",
        "   $y_G = \\frac{A_1 y_1 - A_2 y_2}{A} = \\frac{400(10) - 100(15)}{300} = \\frac{4000 - 1500}{300} = \\frac{2500}{300} = \\frac{25}{3}\\text{ cm}$."
