      "questionAr": "قضيب منتظم وزنه $W = 12\\text{ نيوتن}$ وطوله $2L = 32\\text{ سم}$ متصل بمفصل أملس عند طرفه $A$. أثر عليه ازدواج عزمه $M = 96\\text{ نيوتن.سم}$ في المستوى الرأسي. إذا اتزن القضيب في وضع يميل فيه على الرأسي بزاوية $\\theta$، فاحسب قياس الزاوية $\\theta$.",
