      "questionAr": "شبه منحرف قائم الزاوية $ABCD$ فيه قياس $\\angle A = \\angle B = 90^\\circ$، $AB = 6\\text{ cm}$، و $BC = 4\\text{ cm}$. إذا كان القطران متعامدين ($AC \\perp BD$)، فما طول القاعدة $AD$؟",
