        "   $\\vec{M} = \\begin{vmatrix} \\vec{i} & \\vec{j} & \\vec{k} \\\\ 1 & -2 & 1 \\\\ 2 & -3 & 6 \\end{vmatrix}$.",
        "٣. حساب المركبات:",
