      "hintAr": "لانعدام رد فعل الحائط: بالعزم حول ب نجد عزم الوزن = 50 × 50 = 2500 نيوتن.سم، ويجب أن يعادله عزم الازدواج جـ = 2500 نيوتن.سم.",
