      "questionAr": "ثلاث قوى مستوية $\\vec{F}_1 = a\\vec{i} + 4\\vec{j}\\text{ N}$ تؤثر عند $A(1, 1)$، $\\vec{F}_2 = 3\\vec{i} + b\\vec{j}\\text{ N}$ تؤثر عند $B(0, 1)$، و $\\vec{F}_3 = -5\\vec{i} + 2\\vec{j}\\text{ N}$ تؤثر عند $C(1, 2)$. تكافئ هذه المنظومة ازدواجاً متجه عزمه $\\vec{M} = c\\vec{k}\\text{ N}\\cdot\\text{cm}$. ما قيم كل من $a$ و $b$ و $c$؟",
