        "   $\\vec{M}_B = (1\\vec{j}) \\times (3\\vec{i} - 6\\vec{j}) = -(1)(3)\\vec{k} = -3\\vec{k}$.",
        "   $\\vec{M}_C = (1\\vec{i} + 2\\vec{j}) \\times (-5\\vec{i} + 2\\vec{j}) = [1(2) - 2(-5)]\\vec{k} = (2 + 10)\\vec{k} = +12\\vec{k}$.",
        "3. Sum of moments gives the couple moment:",
